def moving_average(x, k):   
    c = np.cumsum(x)
    return (c[k:] - c[:-k]) / k

def get_phases(x):
    long = len(x) > 20000
    k = 655 if long else 88
    x = moving_average(x, k)
    W = int(5.8 * k)
    grad = moving_average(moving_average(np.diff(x), W // 2), W // 2)
    p0 = np.argmin(grad)
    p1 = np.argmax(grad) + W
    l, r = np.quantile(grad, [0.25, 0.75])
    q = (r - l) * 0.5
    normal = (l - q <= grad) & (grad <= r + q)
    while p0 >= 1 and not normal[max(0, p0 - W // 2)]: p0 -= 1
    while p1 < len(x) and not normal[min(max(p1 - W // 2, 0), len(normal) - 1)]: p1 += 1
    return (p0, p1), x

def calibrate(signal, cal, adc):
    gain, offset, dt = adc
    signal = signal.astype(np.float64) / gain + offset
    flat = cal['flat'].copy()
    linear_corr_flipped = np.flip(cal['linear_corr'], axis=0)
    for x, y in itertools.product(range(signal.shape[1]), range(signal.shape[2])):
        poly = np.poly1d(linear_corr_flipped[:, x, y])
        signal[:, x, y] = poly(signal[:, x, y])
    hot = sigma_clip(cal['dark'], sigma=8, maxiters=5).mask
    signal -= cal['dark'] * dt[:, None, None]
    flat[cal['dead'] | hot] = np.nan
    signal = signal / flat
    mean = np.nanmean(signal, 0)[None, :, :]
    std = np.nanstd(signal, 0)[None, :, :]
    signal[(signal > mean + 8.0 * std) | (signal < mean - 8.0 * std)] = np.nan
    return signal

def get_means(i, pid, j):
    dir = 'train' if i < idx_test else 'test'

    if os.path.exists(f'{prefix}/{dir}/{pid}/x-airs_mean{j}.npy'):
        ass = []
        for ai in range(8):
            ass.append(
                np.load(f'{prefix}/{dir}/{pid}/x-airs_mean{j}-{ai}.npy')
            )
        return (
            np.load(f'{prefix}/{dir}/{pid}/x-airs_mean{j}.npy'),
            np.load(f'{prefix}/{dir}/{pid}/x-fgs1_mean{j}.npy'),
            np.load(f'{prefix}/{dir}/{pid}/x-airs_std{j}.npy'),
            np.load(f'{prefix}/{dir}/{pid}/x-fgs1_std{j}.npy'),
            np.load(f'{prefix}/{dir}/{pid}/x-airs_time{j}.npy'),
            np.load(f'{prefix}/{dir}/{pid}/x-fgs1_time{j}.npy'),
            ass,
        )

    if not os.path.exists(f'{prefix}/{dir}/{pid}/AIRS-CH0_signal_{j}.parquet'):
        return None, None, None, None, None, None, None

    airs = pl.read_parquet(f'{prefix}/{dir}/{pid}/AIRS-CH0_signal_{j}.parquet').to_numpy().reshape(-1, 32, 356)
    fgs1 = pl.read_parquet(f'{prefix}/{dir}/{pid}/FGS1_signal_{j}.parquet').to_numpy().reshape(-1, 32, 32)
    airs_calibration = {}
    fgs1_calibration = {}
    for t in cal_types:
        airs_calibration[t] = pl.read_parquet(f'{prefix}/{dir}/{pid}/AIRS-CH0_calibration_{j}/{t}.parquet').to_numpy().reshape(-1, 32, 356)
        fgs1_calibration[t] = pl.read_parquet(f'{prefix}/{dir}/{pid}/FGS1_calibration_{j}/{t}.parquet').to_numpy().reshape(-1, 32, 32)
    airs = calibrate(airs, airs_calibration, adc['airs'])
    fgs1 = calibrate(fgs1, fgs1_calibration, adc['fgs1'])
    airs_mean = np.nanmean(airs, (1, 2))
    fgs1_mean = np.nanmean(fgs1, (1, 2))
    airs_std = np.nanstd(airs, (1, 2))
    fgs1_std = np.nanstd(fgs1, (1, 2))
    airs_time = np.nanmean(airs, (0))
    fgs1_time = np.nanmean(fgs1, (0))
    a = np.array_split(np.nanmean(airs, 1), 32, axis=1)
    ass = [np.nanmean(x, 1) for x in a]
    return airs_mean, fgs1_mean, airs_std, fgs1_std, airs_time, fgs1_time, ass

def oclip(x):
    return x

def af2f(airs_mean, fgs1_mean, airs_time, fgs1_time, ass, i, pid):
    airs_time = airs_time / np.mean(airs_mean)
    fgs1_time = fgs1_time / np.mean(fgs1_mean)
    airs_mean = airs_mean / np.mean(airs_mean)
    fgs1_mean = fgs1_mean / np.mean(fgs1_mean)
    (a0, a1), ac = get_phases(airs_mean)
    (f0, f1), fc = get_phases(fgs1_mean)
    x1 = np.array(list(map(np.mean, np.array_split(ac, Cv))))
    x2 = np.array(list(map(np.mean, np.array_split(fc, Cv))))
    xx = np.stack([x1, x2], 1)
    xx = np.log(xx)
    def stats(x, m, g=1, h=1):
        try:
            P1 = np.polyfit(np.arange(len(x)) / 1e4, x, 8)
            P2 = np.polyfit(np.arange(len(x)) / 1e4, x, 2)
            P3 = np.polyfit(np.arange(len(x)) / 1e4, x, 1)
        except:
            P1 = [0] * 9
            P2 = [0] * 3
            P3 = [0] * 2
        k = max(int(len(x) * 0.06), 300)
        A = x[:k].mean()
        B = x[-k:].mean()
        Q = B - A
        d = np.diff(x)
        return [
            x.min() / A,
            x.min() / B,
            x.min() / g,
            x.min() / h,
            x.max() / A,
            x.max() / B,
            x.max() / g,
            x.max() / h,
            x.max() - x.min(),
            x.mean(),
            x.max(),
            x.min(),
            Q,
            x.std(),
            (d ** 2).mean(),
            *P1,
            P2[0], P3[0],
        ]
    def ss(x):
        if len(x) == 0:
            x = np.array([1, 1])
        k = max(int(len(x) * 0.06), 300)
        A = x[:k].mean()
        B = x[-k:].mean()
        return [
            x.min() / A,
            x.min() / B,
            x.max() - x.min(),
        ]

    res = []
    for ai in range(32):
        xy = ass[ai][1::2]
        xy = xy / xy.mean()
        (xy0, xy1), xyc = get_phases(xy)
        xyl, xym, xyr = xyc[:xy0], xyc[xy0:xy1], xyc[xy1:]
        res += ss(xym)

    al, am, ar = oclip(ac[:a0]), oclip(ac[a0:a1]), oclip(ac[a1:])
    fl, fm, fr = oclip(fc[:f0]), oclip(fc[f0:f1]), oclip(fc[f1:])
    if len(al) == 0: al = ar[::-1]
    if len(fl) == 0: fl = fr[::-1]
    if len(ar) == 0: ar = al[::-1]
    if len(fr) == 0: fr = fl[::-1]
    acm = ac.mean()
    fcm = fc.mean()
    if len(al) == 0:
        al = np.array([1, 1])
    if len(ar) == 0:
        ar = np.array([1, 1])
    if len(am) == 0:
        am = np.array([1, 1])
    if len(fm) == 0:
        fm = np.array([1, 1])
    if len(fl) == 0:
        fl = np.array([1, 1])
    if len(fr) == 0:
        fr = np.array([1, 1])
    return [
        a0, a1 - a0, f0, f1 - f0, len(ac) - a1, len(fc) - f1,
        *stats(al, acm), *stats(fl, fcm),
        *stats(am, acm, al.mean(), ar.mean()),
        *stats(fm, fcm, fl.mean(), fr.mean()),
        *stats(ar, acm), *stats(fr, fcm),
        acm, fcm,
        *stats(ac, acm), *stats(fc, fcm),
        np.nanstd(airs_time),
        np.nanstd(fgs1_time),
    ] + res, xx

def get_features_partial(i, pid, j):
    airs_mean, fgs1_mean, airs_std, fgs1_std, airs_time, fgs1_time, ass = get_means(i, pid, j)
    if airs_mean is None:
        return []
    airs_mean = airs_mean[1::2]
    fgs1_mean = fgs1_mean[1::2]
    r = [(pid, af2f(airs_mean, fgs1_mean, airs_time, fgs1_time, ass, i, pid))]
    return r


def get_features(i, pid):
    try:
        a = get_features_partial(i, pid, 0)
        return a
    except Exception as e:
        print(i, pid, e, flush=True)
        return [0] * (136 * 2)

